import { Component, OnInit } from '@angular/core';
import { Application } from 'src/app/auth/Models/Application';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { ApplicationService } from 'src/app/service/application/application.service';
import { CompanyService } from 'src/app/service/company/company.service';
import { AuthStateService } from 'src/app/shared/services/auth-state.service';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit {
  company!: Company;
  jobs: Job[] = [];
  applications: Application[] = [];
  pendingApplications: Application[] = [];
  approvedAppplications: Application[] = [];

  constructor(
    private readonly compService: CompanyService,
    private readonly appService: ApplicationService,
    private readonly authState: AuthStateService
  ) {}

  ngOnInit(): void {
    this.loadCompanyById();
    this.loadJobsByCompany();
    this.loadApplicantsByCompany();
    this.loadPendingApplications();
    this.loadHiredApplicants();
  }

  get avatar(): string {
    return this.authState.initialsFromCompany(this.company);
  }

  loadCompanyById(): void {
    const id = this.authState.id;
    if (id === null) {
      return;
    }
    this.compService.getCompanyById(id).subscribe((res: Company) => (this.company = res));
  }

  loadJobsByCompany(): void {
    const id = this.authState.id;
    if (id === null) {
      return;
    }
    this.compService.getJobsByCompany(id).subscribe((res: Job[]) => (this.jobs = res));
  }

  loadApplicantsByCompany(): void {
    const id = this.authState.id;
    if (id === null) {
      return;
    }
    this.appService.getApplicantsByCompany(id).subscribe((res: Application[]) => (this.applications = res));
  }

  loadPendingApplications(): void {
    const id = this.authState.id;
    if (id === null) {
      return;
    }
    this.appService.getPendindApplicants(id).subscribe((res: Application[]) => (this.pendingApplications = res));
  }

  loadHiredApplicants(): void {
    const id = this.authState.id;
    if (id === null) {
      return;
    }
    this.appService.getHiredApplicants(id).subscribe((res: Application[]) => (this.approvedAppplications = res));
  }

  logout(): void {
    this.authState.logout();
  }
}
